'use strict';
// Ember Badlands: 100 authored rescues in 10 connected chapters, building to who left the workshop keys.
// Same fields as story-desert.js.
(globalThis.RescueStories=globalThis.RescueStories||[])[3]={chapters:[
{title:'The Orchard',arc:'The Ash Farm families were saving the pomegranate harvest when the first ashfall came. They scattered across the orchard rows.',levels:[
{n:'Farida',r:'orchard farmer',t:'Ash on the leaves',s:'Farida was covering her pomegranate trees when ash began to fall. She sheltered in the packing shed with a scarf over her face.',k:'found a note in the workshop key box',l:'Thirty harvests on this farm. The trees will grow back. I needed to as well.',x:'The evacuation workshop’s key box has a note inside: “For whoever comes back. Bring the trucks home.”',j:'For whoever comes back.',m:'That’s us. We came back.',h:'ash'},
{n:'Osman',r:'tractor driver',t:'The pump wire',s:'Osman’s tractor stopped beside the irrigation pump, where an ash-heavy power line came down across the farm lane.',k:'knows who fixed the farm tractors',l:'The tractor waits for the ash to stop. So do I.',x:'Every spring someone fixes our tractors for free, leaving a wrench-and-heart sticker on each one.',j:'A wrench in a heart.',m:'That was Dad’s garage sticker.',h:'cable'},
{n:'Zainab',r:'packing-shed worker',t:'The hot shed',s:'Zainab kept twenty pickers in the shade of the packing shed while the heat climbed past forty-five degrees.',k:'saw someone drive away with a truck',l:'Twenty pickers, twenty water bottles, one shed. We made it work.',x:'Before the ash fell, an old woman drove an evacuation truck out of the workshop. She drove like a mechanic.',j:'An old woman driving our truck?',m:'She left the keys behind for us.',h:'heat'},
{n:'Basil',r:'farm hand',t:'The false all-clear',s:'Basil got a message saying the ashfall was over and the road was clear. He checked the farm radio first and stayed under cover.',k:'knows who sent the false all-clear',l:'Ash still falling. Message said clear. I believed the ash.',x:'The false all-clear came from a scrap dealer who wants the workshop trucks for parts.',j:'Scrap? Those trucks save lives.',m:'Then we fix them first.',h:'radio'},
{n:'Nadia',r:'farm manager',t:'The payroll account',s:'Nadia refused to give the farm’s bank code to a caller claiming to be the emergency fund. She locked the office and stayed with the workers.',k:'remembers the woman who taught Dad',l:'The harvest money is the workers’ money. Nobody calls and takes it.',x:'Your dad learned to fix engines here, from the old mechanic. She was strict. He adored her.',j:'Dad had a teacher?',m:'He never talked about her.',h:'code'},
{n:'Karim',r:'clinic driver',t:'The breathing kit',s:'Karim drives the farm clinic van. He sealed the farm’s inhalers and dust masks for the evacuation workshop.',k:'delivered masks to the old mechanic',l:'Masks for the lungs, water for the throat. That’s all of us breathing tonight.',x:'Every ashfall I drop masks at the workshop. Someone is always there first, fixing something.',j:'Someone works there at night.',m:'Alone.',h:'medicine',sup:1},
{n:'Rania',r:'student',t:'The irrigation pond',s:'Rania, 10, watched her kite fall into the irrigation pond. She stayed behind the fence and called for her father.',k:'saw an old woman with a toolbox',l:'The kite can dry out. I’m staying dry.',x:'An old woman with a red toolbox walked past the pond and said, “Good girl. Stay on land.”',j:'A red toolbox.',m:'Dad’s first toolbox was red.',h:'gate'},
{n:'Hakim',r:'orchard guard',t:'The ash dunes',s:'Hakim could have driven through the drifting ash on the farm road. He pulled over, switched off and waited.',k:'saw tracks leading to the mine road',l:'Ash looks soft. It isn’t. It chokes engines and lungs.',x:'Tire tracks went from the workshop to the Copper Mine road. Heavy truck. Careful driver.',j:'Careful driver.',m:'Like Dad.',h:'dust'},
{n:'Selma Aziz',r:'beekeeper',t:'The windmill',s:'Selma Aziz got lost in the ash cloud and waited by the farm’s old windmill, the landmark every farmer knows.',k:'knows what the note’s handwriting looks like',l:'My bees know to stay home in ash. I should have listened.',x:'The note in the key box is neat and slanted, like an engineer’s blueprint.',j:'Neat and slanted.',m:'Dad wrote like that.',h:'landmark'},
{n:'Grandpa Idris',r:'farm founder',t:'Last row',s:'Grandpa Idris founded the Ash Farm. He won’t leave until every family is out of the orchard rows.',k:'read the note in the key box',l:'Sixty harvests. This is the one where everyone came home.',j:'Last one at Ash Farm.',m:'And the note.',h:'verify'}]},
{title:'Shift Change',arc:'The Copper Mine night shift was coming up when the ashfall closed the roads. Miners and their families waited at the pithead.',levels:[
{n:'Mehdi',r:'miner',t:'The lamp room',s:'Mehdi was handing in his lamp when the charger room filled with smoke. He led the shift out to the yard.',k:'recognizes the note’s handwriting',l:'Twenty years underground. Smoke is the one thing I fear.',x:'I know that handwriting. Neat, slanted, a mechanic’s hand. The woman who fixes our lifts writes like that.',j:'She fixes the lifts too?',m:'She fixes everything.',h:'smoke'},
{n:'Graciela',r:'hoist operator',t:'The cage cable',s:'Graciela runs the mine hoist. A power cable from the headframe fell across the path to the gate.',k:'saw the old mechanic at the hoist',l:'I lift a hundred men a day. Tonight I waited to be lifted.',x:'The old mechanic oils our hoist every month. Says, “Machines are like people. Treat them gently.”',j:'Machines are like people.',m:'Dad said that every day.',h:'cable'},
{n:'Raúl',r:'ventilation tech',t:'The hot tunnel',s:'Raúl kept the ventilation running until the heat in the tunnels became dangerous, then brought his crew up.',k:'knows where the old mechanic worked',l:'I keep the air moving underground. Tonight I moved myself.',x:'The old mechanic ran the evacuation workshop for forty years. Then she gave it to her best student.',j:'Her best student.',m:'Dad.',h:'heat'},
{n:'Inés',r:'shift supervisor',t:'The fake drill',s:'Inés got an order to send the shift back underground for a drill. She checked with the mine office and kept everyone up top.',k:'knows who ordered the fake drill',l:'You don’t send miners down in an ashfall. Ever.',x:'The scrap dealer faked the drill to empty the yard. He wanted the mine’s old trucks.',j:'He wants every truck.',m:'Not the evacuation trucks.',h:'radio'},
{n:'Leopoldo',r:'mine engineer',t:'The blasting code',s:'Leopoldo refused to give the blasting system code to a man claiming to be the safety inspector.',k:'saw the mechanic’s old logbook',l:'That code could bring down a mountain. It stays with me.',x:'In the mine office: a logbook of every truck fixed for forty years. Signed “M.”',j:'Just one letter. M.',m:'M for someone Dad knew.',h:'code'},
{n:'Dr. Paz',r:'mine doctor',t:'The lung kit',s:'Dr. Paz sealed the miners’ breathing medicines for the evacuation workshop.',k:'treated the old mechanic',l:'Copper dust and volcanic ash. My miners deserve clean air.',x:'The old mechanic’s lungs are tired. Forty years of exhaust. She still won’t stop working.',j:'She won’t stop.',m:'Like Dad.',h:'medicine',sup:1},
{n:'Tito',r:'student',t:'The tailings pond',s:'Tito, 11, waiting for his miner dad, stayed behind the tailings pond fence when his ball rolled in.',k:'got a wrench from the old mechanic',l:'That pond is poison. Dad told me a hundred times.',x:'The old mechanic gave me a tiny wrench and said: “Every hero starts by fixing small things.”',j:'Fixing small things.',m:'Dad gave me my first wrench too.',h:'gate'},
{n:'Lorena',r:'truck driver',t:'The haul road',s:'Lorena could have driven her ore truck down the haul road under a loose rock face. She waited for the rock crew.',k:'saw the mechanic driving at night',l:'A loaded truck and a loose cliff. Not tonight.',x:'At night I see an evacuation truck leave the workshop, drive the roads, then come back. Every ashfall.',j:'Every ashfall.',m:'She checks the roads for us.',h:'rockfall'},
{n:'Pablo',r:'miner',t:'The headframe',s:'Pablo got lost in the ash cloud and waited under the mine headframe, the shift’s meeting landmark.',k:'heard the mechanic’s name',l:'The headframe has watched over this mine for a century. Tonight it watched over me.',x:'The old miners call her “Mari.” They say she taught every mechanic in the Badlands.',j:'Mari.',m:'Dad called his teacher Mari.',h:'landmark'},
{n:'Señora Ochoa',r:'mine manager',t:'Shift ended',s:'Señora Ochoa runs the Copper Mine. She won’t leave until the whole night shift is accounted for.',k:'knows whose handwriting it is',l:'Three hundred miners up. Shift ended.',j:'Last one at the Copper Mine.',m:'And the handwriting.',h:'verify'}]},
{title:'The Gauge Room',arc:'The Heat Station turns the Badlands’ volcanic heat into power. When the ash came, its engineers stayed to keep the gauges safe.',levels:[
{n:'Samir',r:'plant engineer',t:'The turbine hall',s:'Samir got his crew out of the turbine hall when a seal failed and steam smoke filled it.',k:'found the gauges already reset',l:'Steam is power. Loose steam is danger. We let it go.',x:'The ashfall gauges were reset before we got here. Someone knew the ash schedule by heart.',j:'By heart.',m:'Forty years of ashfalls.',h:'smoke'},
{n:'Noor Haddad',r:'line technician',t:'The transformer',s:'Noor Haddad is stranded behind a transformer cable that fell in the ash.',k:'knows who keeps the ash schedule',l:'I fix lines that light a whole valley. Tonight I left one alone.',x:'The ash schedule on the wall is in the same neat, slanted handwriting as the key-box note.',j:'Same handwriting.',m:'Same person.',h:'cable'},
{n:'Ilyas',r:'control room operator',t:'The heat alarm',s:'Ilyas kept the control room running until the cooling failed and the heat rose. Then he took his team outside to the shade.',k:'heard the mechanic on the radio',l:'Forty-eight degrees inside. I chose the shade.',x:'On the station radio, an old woman’s voice: “Ash at eleven. Keep the trucks covered.”',j:'Keep the trucks covered.',m:'She’s protecting the trucks.',h:'heat'},
{n:'Aylin',r:'scheduler',t:'The fake shutdown',s:'Aylin got an order to shut off the workshop’s power for “ash safety.” She called the plant manager and refused.',k:'knows who ordered the shutdown',l:'Without power the workshop can’t fix anything. That was the point.',x:'The scrap dealer wanted the workshop dark so the trucks would stay broken.',j:'He wants them broken.',m:'We want them running.',h:'radio'},
{n:'Kerem',r:'security officer',t:'The plant gate',s:'Kerem refused to give the plant gate code to a man claiming to be from the power company.',k:'saw who visits the workshop',l:'This plant lights ten towns. The gate stays shut.',x:'Every night the same old truck parks at the workshop. The driver has silver hair and oil on her hands.',j:'Silver hair.',m:'Oil on her hands. Like Dad.',h:'code'},
{n:'Dilara',r:'plant medic',t:'The burns kit',s:'Dilara, the plant medic, sealed the burn and heat-stroke kit for the evacuation workshop.',k:'treated the mechanic’s burns',l:'Steam burns, heat stroke, ash eyes. I’ve got a cure for each.',x:'Last month the old mechanic burned her hand fixing a truck. She said, “Truck 7 doesn’t fix itself.”',j:'Truck 7.',m:'Dad’s truck had a 7 on it.',h:'medicine',sup:1},
{n:'Emre',r:'student',t:'The cooling pond',s:'Emre, 12, on a school trip, stayed behind the cooling pond fence when his cap blew in.',k:'saw the mechanic’s truck number',l:'The pond is hotter than a bath. Way hotter. No thanks.',x:'The old mechanic’s truck has a big 7 painted on the door, faded and patched.',j:'Truck 7.',m:'Dad drove Truck 7.',h:'gate'},
{n:'Selin Kaya',r:'road crew',t:'The steam vent',s:'Selin Kaya could have driven past a new steam vent on the station road. She stopped and waited for the plant crew.',k:'saw Truck 7 on the road',l:'New vents open every ashfall. I don’t drive over them.',x:'Truck 7 drove past at dawn, towing a broken evacuation van toward the viaduct.',j:'Towing a van alone.',m:'She’s fixing them all.',h:'crossing'},
{n:'Berk',r:'engineer',t:'The red chimney',s:'Berk got lost in the ash and waited by the plant’s red chimney, the landmark you can see from anywhere.',k:'knows what the mechanic said about Dad',l:'The red chimney is ugly. Tonight it was beautiful.',x:'She told me: “My best student had two kids. One day they’ll come back to the workshop.”',j:'She knew about us.',m:'Dad told her about us.',h:'landmark'},
{n:'Director Aksoy',r:'plant director',t:'Gauges steady',s:'Director Aksoy runs the Heat Station. He won’t leave until every gauge is safe and every engineer is out.',k:'knows who reset the gauges',l:'The gauges are steady. So are my people.',j:'Last one at the Heat Station.',m:'And the gauges.',h:'verify'}]},
{title:'The Painters',arc:'The Red Viaduct is covered in murals by the Badlands’ street painters. Tonight they were painting when the ash closed the roads.',levels:[
{n:'Paloma',r:'mural painter',t:'The paint store',s:'Paloma got everyone out when the paint store under the viaduct started smoking.',k:'painted a wrench in a heart',l:'I paint the viaduct. Tonight I painted an escape route on my friends’ faces.',x:'The newest graffiti on the viaduct: a wrench inside a heart. The old workshop’s logo.',j:'Dad’s logo.',m:'The workshop’s logo.',h:'smoke'},
{n:'Andrés',r:'street artist',t:'The scaffold cable',s:'Andrés is stuck on the viaduct path, behind a scaffold light cable that fell in the ash.',k:'knows who asked for the mural',l:'Spray paint and live wires don’t mix. I’m not touching it.',x:'An old woman paid me to paint the wrench-and-heart. She said, “So they’ll find their way home.”',j:'So we’ll find our way home.',m:'She painted a sign for us.',h:'cable'},
{n:'Luna',r:'painter',t:'Ash on the mural',s:'Luna covered her fresh mural with a tarp when the ash came, then sheltered in the viaduct’s arch.',k:'saw the old woman painting',l:'Paint dries. Lungs don’t heal so fast.',x:'The old woman painted a small “7” inside the heart, very carefully.',j:'A 7.',m:'Truck 7.',h:'ash'},
{n:'Marco Rossi',r:'gallery owner',t:'The fake exhibition',s:'Marco Rossi got a message that the mural festival had moved to the scrapyard. He called the organizers and stayed put.',k:'knows why the scrapyard was named',l:'Art doesn’t move to a scrapyard. Never.',x:'The scrap dealer wanted artists at his scrapyard to cover up the trucks he’d stolen.',j:'He stole trucks?',m:'Two evacuation trucks. We need them back.',h:'radio'},
{n:'Consuelo',r:'art teacher',t:'The school tablets',s:'Consuelo refused to give the school tablets’ password to a caller claiming to be the district.',k:'taught Dad to draw',l:'Those tablets hold my students’ art. Nobody else gets in.',x:'I taught your dad to draw when he was ten. He drew trucks. Always trucks. And a woman named Mari.',j:'Mari again.',m:'Dad’s teacher.',h:'code'},
{n:'Amalia',r:'pharmacist',t:'The paint-fume kit',s:'Amalia, the viaduct pharmacist, sealed the painters’ respirators and eye drops for the workshop.',k:'filled the old mechanic’s prescription',l:'Ash, paint fumes, cigarettes. My painters breathe badly. Not tonight.',x:'The old mechanic’s prescription is signed “Marisol.” She’s seventy-eight.',j:'Marisol.',m:'Mari. Marisol.',h:'medicine',sup:1},
{n:'Javi',r:'student',t:'The aqueduct channel',s:'Javi, 9, saw his spray can roll into the viaduct’s water channel and stayed behind the railing.',k:'met Marisol at the viaduct',l:'I want to paint like Paloma. I want to be alive first.',x:'Marisol showed me how to hold a wrench. She said: “Your hands can fix the world.”',j:'Your hands can fix the world.',m:'Dad said that too.',h:'gate'},
{n:'Teresa',r:'bus driver',t:'The viaduct road',s:'Teresa could have driven her bus under the viaduct, where loose stone was falling. She stopped and waited.',k:'saw Truck 7 at the quarry',l:'The viaduct is a hundred years old. I’m not testing it tonight.',x:'Truck 7 was parked at the South Quarry. Marisol was unloading an engine.',j:'An engine.',m:'For an evacuation truck.',h:'rockfall'},
{n:'Hugo Ruiz',r:'painter',t:'The giant sun mural',s:'Hugo Ruiz got lost in the ash cloud and waited under the giant painted sun, the painters’ meeting point.',k:'saw what Marisol painted last',l:'That sun has been painted over ten times. It still shines.',x:'Marisol’s last painting: two small figures beside a big truck. Under it: “Bring them home.”',j:'Two small figures.',m:'Us.',h:'landmark'},
{n:'Maestra Iris',r:'mural collective leader',t:'Brushes down',s:'Maestra Iris leads the painters’ collective. She won’t leave the Red Viaduct until every painter is safe.',k:'knows who painted the heart',l:'Fifty painters, fifty brushes, one viaduct. All safe.',j:'Last one at the Red Viaduct.',m:'And the heart.',h:'verify'}]},
{title:'The Quarry Crew',arc:'The South Quarry crew blast and haul stone for the whole Badlands. Tonight they were trapped by ash and falling rock.',levels:[
{n:'Arturo',r:'blaster',t:'The fuse store',s:'Arturo got everyone away from the quarry fuse store when ash smoke drifted near it.',k:'found an engine wrapped in a blanket',l:'Fuses and fire. I keep them apart. Always.',x:'At the back of the quarry: a spare engine, wrapped in a blanket, tagged “Truck 7.”',j:'Wrapped in a blanket.',m:'Like something precious.',h:'smoke'},
{n:'Yesenia',r:'crusher operator',t:'The crusher line',s:'Yesenia is stuck behind the stone crusher’s power line, which fell across the yard.',k:'saw Marisol bring the engine',l:'I crush rocks all day. Tonight a wire nearly crushed my plans.',x:'Marisol brought that engine in Truck 7 last week. Said she was saving it “for when they come back.”',j:'For when we come back.',m:'She’s been waiting.',h:'cable'},
{n:'Eusebio',r:'loader driver',t:'The hot pit',s:'Eusebio kept his crew in the shade of the loader shed while the quarry pit baked under the ash cloud.',k:'helped Marisol lift the engine',l:'The pit gets hot as an oven. We stayed in the shade.',x:'I helped Marisol lift the engine. She’s seventy-eight and she lifted half of it.',j:'Seventy-eight.',m:'Stronger than both of us.',h:'heat'},
{n:'Cecilia',r:'quarry dispatcher',t:'The fake haul order',s:'Cecilia got an order to send all trucks to the scrapyard. She checked with the quarry owner and held them.',k:'knows who wanted the trucks',l:'Trucks go where the work is. Not to a scrapyard.',x:'The scrap dealer wanted every truck in the Badlands. Including the evacuation trucks.',j:'He wants to sell them.',m:'People need them.',h:'radio'},
{n:'Fermín',r:'quarry foreman',t:'The explosives code',s:'Fermín refused to give the explosives store code to a man claiming to be a mining inspector.',k:'knows Marisol’s story',l:'That code could level a hill. It stays in my head.',x:'Marisol taught half the quarry mechanics. She retired when your dad took over the workshop.',j:'When Dad took over.',m:'Then Dad disappeared, and she came back.',h:'code'},
{n:'Nurse Inma',r:'quarry nurse',t:'The dust kit',s:'Nurse Inma sealed the quarry’s eye-wash and breathing kit for the evacuation workshop.',k:'treated Marisol’s back',l:'Stone dust and ash. The lungs remember everything.',x:'Marisol’s back hurts from lifting engines. She said, “Pain is fine. Broken trucks are not.”',j:'Broken trucks are not fine.',m:'Dad would agree.',h:'medicine',sup:1},
{n:'Pepe',r:'student',t:'The quarry lake',s:'Pepe, 10, stayed behind the quarry lake fence when his toy truck rolled into the deep water.',k:'got a ride in Truck 7',l:'The lake is deep and cold. Dad said never. So never.',x:'Marisol gave me a ride in Truck 7. It smells like oil and peppermint.',j:'Oil and peppermint.',m:'Dad’s truck smelled like that.',h:'gate'},
{n:'Rocío',r:'hauler',t:'The rockface',s:'Rocío could have driven under the cracked quarry face. She stopped and waited for the rock crew.',k:'saw Truck 7 towing',l:'Rocks don’t warn you twice.',x:'Truck 7 towed a broken van out of the quarry, heading for Glass Flats.',j:'Glass Flats.',m:'She’s gathering the trucks.',h:'rockfall'},
{n:'Gonzalo',r:'quarry worker',t:'The yellow crane',s:'Gonzalo got lost in the ash and waited by the old yellow crane, the quarry’s meeting landmark.',k:'knows what Marisol is building',l:'The yellow crane hasn’t worked in years. Tonight it guided me home.',x:'She’s building a full evacuation fleet. Seven trucks. One for every road out.',j:'Seven trucks.',m:'And Truck 7 leads them.',h:'landmark'},
{n:'Doña Remedios',r:'quarry owner',t:'Quarry quiet',s:'Doña Remedios owns the South Quarry. She won’t leave until every worker and truck is safe.',k:'kept the Truck 7 engine safe',l:'Stone lasts forever. People don’t. Tonight they did.',j:'Last one at the South Quarry.',m:'And the engine.',h:'verify'}]},
{title:'The Glassblowers',arc:'Glass Flats is where artisans turn volcanic sand into glass. Tonight their furnaces were lit when the ash cloud rolled in.',levels:[
{n:'Mirza',r:'glassblower',t:'The furnace room',s:'Mirza got his apprentices out when ash clogged the furnace vents and smoke filled the studio.',k:'saw someone towing a truck at night',l:'Glass needs heat. People need air. I chose air.',x:'At midnight, someone towed a broken truck across Glass Flats toward the Firebreak. Alone.',j:'Alone again.',m:'She always works alone.',h:'smoke'},
{n:'Rosaura',r:'glass artist',t:'The kiln wire',s:'Rosaura is stuck behind a kiln power cable that fell in the ash outside her studio.',k:'made a glass key for the workshop',l:'I make beautiful things from fire. Tonight I stayed away from it.',x:'Marisol commissioned a glass key from me. Clear glass, with a tiny wrench inside.',j:'A glass key.',m:'For the workshop.',h:'cable'},
{n:'Malik Saeed',r:'sand hauler',t:'The salt flats',s:'Malik Saeed kept his crew in the truck cab while the heat on the open flats became dangerous.',k:'tracked the towing truck',l:'The flats are a mirror in the heat. We didn’t go out in it.',x:'The tracks show Truck 7 towing two broken vans. Seventy-eight years old and towing two vans.',j:'She’s amazing.',m:'She’s Dad’s teacher.',h:'heat'},
{n:'Valentina',r:'studio manager',t:'The fake buyer',s:'Valentina got a message from a “buyer” asking the artists to bring their glass to the scrapyard. She called the gallery first and stayed.',k:'knows who the buyer was',l:'Real buyers don’t meet at scrapyards in an ashfall.',x:'The buyer was the scrap dealer. He wanted the artists out so he could take their truck.',j:'Every truck.',m:'He wants every truck.',h:'radio'},
{n:'Tariq Nasser',r:'furnace engineer',t:'The furnace controls',s:'Tariq Nasser refused to give the furnace control password to a man claiming to be the gas company.',k:'helped Marisol fix a furnace',l:'One wrong setting and the studio melts. It stays locked.',x:'Marisol fixed our furnace once. She said: “Heat is a tool. Respect it, and it respects you.”',j:'Respect it.',m:'Dad’s rule too.',h:'code'},
{n:'Dr. Solis',r:'studio doctor',t:'The burn kit',s:'Dr. Solis, who treats the glassblowers, sealed the burn and eye-injury kit for the evacuation workshop.',k:'treated Marisol’s eyes',l:'Glass, fire and ash. My patients are brave and careless.',x:'Marisol’s eyes are weak now. She fixes engines by feel. She knows every bolt in Truck 7.',j:'By feel.',m:'After fifty years.',h:'medicine',sup:1},
{n:'Lucho',r:'student',t:'The cooling trough',s:'Lucho, 11, an apprentice, stayed back from the cooling trough when his glass bead fell in.',k:'got a glass truck from Marisol',l:'The trough is hotter than it looks. Everything here is.',x:'Marisol gave me a tiny glass truck with a 7 on it. She said, “For luck.”',j:'For luck.',m:'Dad said that when he left.',h:'gate'},
{n:'Catalina',r:'courier',t:'The fissure road',s:'Catalina could have driven across a fresh fissure on the flats road. She stopped and waited for the road crew.',k:'saw Marisol at the Firebreak',l:'The road cracked open like glass. I didn’t drive into it.',x:'At the Firebreak, Marisol was helping the volunteers load a fire truck. Then she was gone.',j:'She helps, then vanishes.',m:'Like a ghost.',h:'crossing'},
{n:'Abel',r:'glassblower',t:'The glass tower',s:'Abel got lost in the ash and waited by the glass tower sculpture, the Flats’ landmark.',k:'heard Marisol talk about her student',l:'The tower catches every light. Even ash light.',x:'Marisol said: “My best student drove a tow truck. He saved more people than all of us.”',j:'Dad.',m:'She’s proud of him.',h:'landmark'},
{n:'Maestro Celio',r:'master glassblower',t:'Furnaces cold',s:'Maestro Celio, the master glassblower, won’t leave Glass Flats until every apprentice is safe.',k:'saw where the towed truck went',l:'Fifty years of glass. Tonight, I made sure the glassmakers were whole.',j:'Last one at Glass Flats.',m:'And the tow tracks.',h:'verify'}]},
{title:'The Volunteers',arc:'The Firebreak volunteer crew cut lines to stop ash fires reaching the towns. Tonight they held the line and got cut off.',levels:[
{n:'Captain Alba',r:'volunteer captain',t:'The fire line',s:'Captain Alba pulled her crew back from the fire line when the wind turned, and is waiting on the burnt-out break.',k:'knows the retired mechanic who helps',l:'We hold the line. Tonight the line held us.',x:'A retired mechanic helps every evacuation, fixes our pump, then vanishes before we can thank her.',j:'She vanishes.',m:'She doesn’t want thanks.',h:'smoke'},
{n:'Nacho',r:'volunteer',t:'The pump cable',s:'Nacho, a young volunteer, is stuck behind the water pump’s power cable, which fell across the trail.',k:'saw Marisol fix the pump',l:'First season. Already learned a lot. Mostly about wires.',x:'Marisol fixed our pump in ten minutes. Then she said, “Go save your town,” and drove away.',j:'Go save your town.',m:'That’s our job too.',h:'cable'},
{n:'Amparo',r:'volunteer',t:'The ash cloud',s:'Amparo got caught when a fresh ash cloud rolled over the firebreak, and is sheltering in the crew truck.',k:'heard Marisol talk about Dad',l:'Ash in your eyes, ash in your mouth. I closed the truck and waited.',x:'Marisol said your dad trained here as a volunteer. She was his first crew boss.',j:'Dad fought fires?',m:'He never told us.',h:'ash'},
{n:'Octavio',r:'volunteer',t:'The fake orders',s:'Octavio got an order to abandon the firebreak and drive to the scrapyard. He checked with Captain Alba and stayed.',k:'knows who sent the orders',l:'You don’t abandon a firebreak because a text says so.',x:'The scrap dealer wanted the crew’s fire truck. He was going to sell it.',j:'A fire truck.',m:'He’ll sell anything.',h:'radio'},
{n:'Elvira',r:'radio volunteer',t:'The crew radio',s:'Elvira refused to give the crew’s radio channel code to a caller claiming to be the fire service.',k:'heard Marisol on the radio',l:'Our radio keeps us alive. Nobody else gets in.',x:'Marisol radioed tonight: “Firebreak, you have water. I fixed the pump. Don’t look for me.”',j:'Don’t look for me.',m:'We’re looking anyway.',h:'code'},
{n:'Medic Rafa',r:'volunteer medic',t:'The burn kit',s:'Medic Rafa, the crew’s volunteer medic, sealed the burn and smoke kit for the evacuation workshop.',k:'treated Marisol’s hands',l:'Burns, smoke, exhaustion. I’ve seen them all tonight.',x:'Marisol’s hands are cracked from years of engine work. She said, “These hands taught your dad.”',j:'These hands taught Dad.',m:'Let’s hold them.',h:'medicine',sup:1},
{n:'Gabi',r:'student',t:'The water tank',s:'Gabi, 12, a volunteer’s daughter, stayed behind the fence at the firebreak’s water tank when her phone fell in.',k:'saw Marisol leave toward the foundry',l:'I can get a new phone. Mom can’t get a new me.',x:'Truck 7 drove off toward the Old Foundry. The back was full of tools.',j:'The Old Foundry.',m:'Dad’s old workshop was near there.',h:'gate'},
{n:'Lázaro',r:'volunteer',t:'The burnt bridge',s:'Lázaro could have crossed the scorched footbridge on the firebreak. He waited for the all-clear.',k:'knows why Marisol vanishes',l:'A burnt bridge is just a trap with planks.',x:'She vanishes because she doesn’t want anyone to stop her. She has a promise to keep.',j:'A promise.',m:'To Dad.',h:'crossing'},
{n:'Sofía Reyes',r:'volunteer',t:'The fire bell',s:'Sofía Reyes got lost in the ash and waited by the old fire bell, the crew’s meeting point.',k:'is related to the Reyes family',l:'Same last name as your dad. Distant cousin. Small badlands.',x:'Marisol told me: “Tomás’s kids are coming. Make sure they find the way.”',j:'Tomás. Dad.',m:'She knows his name.',h:'landmark'},
{n:'Chief Benítez',r:'volunteer chief',t:'Line held',s:'Chief Benítez won’t leave the Firebreak until every volunteer is accounted for.',k:'knows who helps every evacuation',l:'The line held. Every volunteer home. Best night of my life.',j:'Last one at the Firebreak.',m:'And the mechanic.',h:'verify'}]},
{title:'The Apprentices',arc:'The Old Foundry trains young mechanics. Tonight the apprentices were working late when the ash trapped them.',levels:[
{n:'Mateus',r:'apprentice',t:'The forge',s:'Mateus got the other apprentices out when the forge chimney clogged with ash and smoked.',k:'found the tools oiled and ready',l:'First year apprentice. First lesson: get out of the smoke.',x:'The foundry tools were freshly oiled and laid out in a row, exactly the way Dad said his teacher did.',j:'Exactly like Dad’s workshop.',m:'She taught him that.',h:'smoke'},
{n:'Rosa Lima',r:'apprentice',t:'The welding cable',s:'Rosa Lima is stuck behind a welding cable that fell across the foundry floor.',k:'learned from Marisol',l:'I weld steel. I don’t weld myself to live cables.',x:'Marisol teaches us every Sunday. She says: “Lay out your tools like a surgeon.”',j:'Like a surgeon.',m:'Dad’s tools were always perfect.',h:'cable'},
{n:'Diego Mora',r:'apprentice',t:'The furnace heat',s:'Diego Mora kept the youngest apprentices in the cool storeroom while the foundry heat rose.',k:'saw Marisol’s notebook',l:'I want to be a mechanic. Being a survivor comes first.',x:'In Marisol’s notebook: “Truck 7 is Tomás’s truck. Fix it for his kids.”',j:'Truck 7 is Dad’s truck.',m:'She’s fixing Dad’s truck for us.',h:'heat'},
{n:'Itzel',r:'apprentice',t:'The fake job',s:'Itzel got a message offering big money to strip trucks at the scrapyard. She asked Marisol first and stayed.',k:'knows what the scrap dealer wanted',l:'Easy money in an ashfall? That’s not a job. That’s a trap.',x:'The scrap dealer wanted apprentices to strip Truck 7. Marisol hid it.',j:'She hid Dad’s truck.',m:'To save it for us.',h:'radio'},
{n:'Leandro',r:'foundry clerk',t:'The parts inventory',s:'Leandro refused to give the parts inventory password to a man claiming to be a supplier.',k:'tracked parts for Truck 7',l:'Every bolt in this foundry is counted. Nobody steals a bolt.',x:'Marisol has ordered every part for Truck 7 for eight years. One part at a time.',j:'Eight years.',m:'Since Mom died.',h:'code'},
{n:'Nurse Clara',r:'foundry nurse',t:'The foundry kit',s:'Nurse Clara sealed the foundry’s burns and cuts kit for the evacuation workshop.',k:'treats Marisol every week',l:'Apprentices burn, cut and bruise. Then they learn.',x:'Marisol said: “When Truck 7 runs, I can rest.”',j:'When Truck 7 runs.',m:'Then we make it run.',h:'medicine',sup:1},
{n:'Tomasito',r:'student',t:'The quench tank',s:'Tomasito, 9, the youngest apprentice, stayed back from the quench tank when his glove fell in.',k:'is named after Dad',l:'My name is Tomasito. Little Tomás. After your dad.',x:'Marisol named me. She says your dad was the best boy she ever taught.',j:'Named after Dad.',m:'Dad would love that.',h:'gate'},
{n:'Lucas',r:'apprentice',t:'The collapsing wall',s:'Lucas could have run past the foundry’s cracked wall. He waited for the all-clear.',k:'saw Truck 7 leave for the ridge',l:'The foundry is a hundred years old. I gave it respect.',x:'Truck 7 left the foundry tonight, running on its own engine. Marisol drove toward Ember Ridge.',j:'It runs.',m:'Dad’s truck runs.',h:'rockfall'},
{n:'Camila',r:'apprentice',t:'The old anvil',s:'Camila got lost in the ash and waited by the giant old anvil, the foundry’s meeting point.',k:'heard Marisol’s promise',l:'The anvil has seen a hundred years of mechanics. Tonight it saw me.',x:'Marisol promised Tomás: “If anything happens, I’ll keep your truck ready for your kids.”',j:'She kept her promise.',m:'Eight years.',h:'landmark'},
{n:'Master Faustino',r:'foundry master',t:'Fires out',s:'Master Faustino runs the Old Foundry. He won’t leave until every apprentice is safe.',k:'knows whose tools were laid out',l:'The fires are out. Every apprentice is home.',j:'Last one at the Old Foundry.',m:'And the tools.',h:'verify'}]},
{title:'Ridge Radio',arc:'Ember Ridge is the last village before the crossing. Its community radio keeps the Badlands connected through every ashfall.',levels:[
{n:'DJ Ramiro',r:'radio host',t:'The studio',s:'DJ Ramiro got out of the radio studio when ash clogged its cooling fans and it smoked.',k:'got a message for Mara',l:'I talk all night to keep people company. Tonight I had to stop talking.',x:'A message came in for the radio: “Truck 7 is ready. Tell Mara her dad’s teacher kept her promise.”',j:'For you, Mara.',m:'She kept her promise.',h:'smoke'},
{n:'Luisa',r:'radio engineer',t:'The antenna',s:'Luisa is stuck below the radio antenna after its cable fell in the ash.',k:'broadcast Marisol’s message',l:'I keep the signal going. Tonight the signal kept me.',x:'I broadcast Marisol’s message to the whole Badlands. Every evacuation driver heard it.',j:'Every driver heard.',m:'Every truck is coming.',h:'cable'},
{n:'Abuela Chayo',r:'village elder',t:'The ash garden',s:'Abuela Chayo sheltered in her kitchen when ash covered her garden, waiting with a pot of beans.',k:'knew Marisol as a girl',l:'Eighty years in this village. The ash comes. The ash goes. We stay.',x:'Marisol and I grew up together. She fixed bikes at ten. Trucks at fifteen. Hearts all her life.',j:'Hearts all her life.',m:'Like the wrench and the heart.',h:'ash'},
{n:'Fabián',r:'radio volunteer',t:'The fake broadcast',s:'Fabián got a script telling drivers to bring their trucks to the scrapyard. He checked with Luisa and refused to read it.',k:'knows who wrote the script',l:'The radio tells the truth. That’s all it does.',x:'The scrap dealer wrote it. He’s been caught now. Marisol called the police.',j:'He’s caught.',m:'The trucks are safe.',h:'radio'},
{n:'Señor Valdés',r:'village mayor',t:'The village fund',s:'Señor Valdés refused to give the village emergency fund code to a caller claiming to be the government.',k:'knows Marisol’s plan',l:'The village fund is the village’s. Nobody else’s.',x:'Marisol’s plan: seven trucks, one for each road out. Truck 7 leads them all.',j:'Seven trucks.',m:'And we drive the first one.',h:'code'},
{n:'Nurse Pilar',r:'village nurse',t:'The ash kit',s:'Nurse Pilar sealed the village’s ash masks and eye drops for the evacuation workshop.',k:'checked Marisol’s health',l:'Ash in the lungs is a slow danger. I fight it slowly.',x:'Marisol is tired, but happy. She said: “I just need to see Tomás’s kids drive Truck 7.”',j:'She wants to see us.',m:'Then let’s go.',h:'medicine',sup:1},
{n:'Chuy',r:'student',t:'The village well',s:'Chuy, 10, stayed behind the fence at the village well when his marble fell in.',k:'heard Truck 7’s horn',l:'The well is deep. My marble is gone. I’m here.',x:'I heard Truck 7’s horn: three short honks. Abuela says it means “I’m okay.”',j:'Three honks.',m:'Dad’s signal.',h:'gate'},
{n:'Esteban',r:'road worker',t:'The ridge road',s:'Esteban could have driven down the ash-covered ridge road. He switched off his lights and waited.',k:'saw Truck 7 heading for the crossing',l:'Ash on a ridge road is ice with attitude.',x:'Truck 7 went down toward Safe Crossing, lights on. Marisol was driving.',j:'She’s at the crossing.',m:'Waiting for us.',h:'dust'},
{n:'Chela',r:'village shopkeeper',t:'The church bell',s:'Chela got lost in the dark ash cloud and waited under the church bell, the village meeting point.',k:'knows what Marisol will say',l:'The bell has called us home for two hundred years.',x:'Marisol told me she’ll say: “You came back. Now bring them all home.”',j:'Bring them all home.',m:'That’s what we do.',h:'night'},
{n:'Father Ignacio',r:'village priest',t:'All safe',s:'Father Ignacio refused to leave Ember Ridge until every family in the village was safe.',k:'heard the radio message',l:'Every soul in the village is safe. Thank you.',j:'Last one at Ember Ridge.',m:'And the message.',h:'verify'}]},
{title:'Truck 7',arc:'The evacuation convoy waits at Safe Crossing. Marisol has brought every truck she could fix, and she’s waiting for Tomás’s kids.',levels:[
{n:'Driver Ana Lucía',r:'convoy driver',t:'Engine smoke',s:'Driver Ana Lucía pulled her convoy truck over when its engine smoked, and got her passengers out.',k:'drove a truck Marisol fixed',l:'Marisol fixed this truck. Even smoking, it got us here.',x:'Marisol fixed every truck in the convoy. Six of them. Truck 7 is the seventh.',j:'Seven trucks.',m:'One for each road.',h:'smoke'},
{n:'Driver Ezequiel',r:'convoy driver',t:'The crossing cable',s:'Driver Ezequiel is stuck behind a power cable that fell across the crossing approach.',k:'saw Marisol waiting',l:'I drove through three ashfalls. A wire nearly stopped me.',x:'Marisol is standing next to Truck 7 with a thermos of coffee. She’s smiling.',j:'Coffee.',m:'Dad always had coffee.',h:'cable'},
{n:'Driver Yolanda',r:'convoy driver',t:'The heat',s:'Driver Yolanda kept her passengers in the shade of her truck while the crossing baked.',k:'heard Marisol’s story',l:'Forty-five degrees and a full truck. We stayed in the shade.',x:'Marisol told us: “Tomás kept the porch light on. I kept his truck running.”',j:'The porch light.',m:'Dad’s porch light.',h:'heat'},
{n:'Driver Ramiro Sosa',r:'convoy driver',t:'The fake route',s:'Driver Ramiro Sosa got a new route telling the convoy to wait at the scrapyard. He checked with Marisol and refused.',k:'knows the scrap dealer is gone',l:'The convoy goes one way: out. Safely.',x:'The scrap dealer is gone. The police took him. The trucks are safe forever.',j:'Safe forever.',m:'Because of Marisol.',h:'radio'},
{n:'Driver Benita',r:'convoy coordinator',t:'The convoy codes',s:'Driver Benita refused to give the convoy’s radio codes to a caller pretending to be the police.',k:'saw Marisol’s key',l:'Seven trucks, one radio code. It stays secret.',x:'Marisol holds a glass key with a tiny wrench inside. The workshop key.',j:'The glass key.',m:'From Glass Flats.',h:'code'},
{n:'Medic Rosario',r:'convoy medic',t:'The convoy kit',s:'Medic Rosario sealed the convoy’s first-aid kit for the evacuation workshop.',k:'treated Marisol tonight',l:'I patch up drivers. Tonight I patched up a legend.',x:'Marisol’s heart is strong. She said: “Strong enough to see this through.”',j:'Strong enough.',m:'Like Dad.',h:'medicine',sup:1},
{n:'Maite',r:'student',t:'The crossing river',s:'Maite, 8, stayed behind the fence when her toy fell in the river at Safe Crossing.',k:'got a peppermint from Marisol',l:'The river is fast. My toy is gone. That’s okay.',x:'Marisol gave me a peppermint and said: “Tomás always had peppermints too.”',j:'Peppermints.',m:'Dad’s peppermints.',h:'gate'},
{n:'Driver Teo',r:'convoy driver',t:'The crossing bridge',s:'Driver Teo could have rushed across the crossing bridge before the all-clear. He waited.',k:'saw Truck 7 up close',l:'The bridge waits for everyone. I waited for it.',x:'Truck 7 has a new engine, new tires, and the old wrench-and-heart sticker on the door.',j:'The sticker.',m:'Dad’s sticker.',h:'crossing'},
{n:'Driver Maribel',r:'convoy driver',t:'The crossing flag',s:'Driver Maribel got lost in the ash and waited by the crossing flag, the convoy meeting point.',k:'knows Marisol is waiting for you',l:'The flag never moves. That’s why we chose it.',x:'Marisol is at Truck 7, waiting for you. She’s been waiting eight years.',j:'Eight years.',m:'Let’s not make her wait longer.',h:'landmark'},
{n:'Marisol',r:'retired mechanic',t:'Dad’s teacher',s:'Marisol, 78, the mechanic who taught Dad, waits beside Truck 7 at Safe Crossing with the workshop’s glass key.',k:'kept her promise to Tomás',l:'Tomás asked me to keep his truck ready. Here it is. Drive it home.',j:'Marisol.',m:'Thank you for keeping Dad’s truck.',h:'verify'}]}
]};
